import { Component, Element, Host, Prop, h } from "@stencil/core";

/**
 * Displays labeled data pairs using semantic dl/dt/dd markup.
 *
 * Automatically styles dt (secondary text) and dd (primary text) elements.
 * Multiple dl elements create a grouped layout with consistent spacing.
 *
 * @since 2.18.10
 * @status beta
 *
 * @slot - One or more dl elements containing dt/dd pairs.
 *
 * @example
 * // Row layout (horizontal key-value)
 * <hbr-key-value-pairs direction="row">
 *   <dl><dt>Status</dt><dd>Active</dd></dl>
 *   <dl><dt>Created</dt><dd>Jan 10, 2026</dd></dl>
 * </hbr-key-value-pairs>
 *
 * @example
 * // Column layout (stacked)
 * <hbr-key-value-pairs direction="column">
 *   <dl><dt>Description</dt><dd>Detailed text...</dd></dl>
 * </hbr-key-value-pairs>
 *
 * @example
 * // Right-aligned values
 * <hbr-key-value-pairs direction="row" align="end">
 *   <dl><dt>Total</dt><dd>$1,234.56</dd></dl>
 * </hbr-key-value-pairs>
 */
@Component({
	tag: "hbr-key-value-pairs",
	styleUrl: "key-value-pairs.scss",
	scoped: false,
})
export class KeyValuePairs {
	@Element() el: HTMLElement;

	/** Layout: 'row' for horizontal key-value, 'column' for stacked. Default: row. */
	@Prop() direction: "row" | "column" = "row";

	/** Spacing preset: 'sm' for compact, 'md' for standard. Default: md. */
	@Prop() size: "sm" | "md" = "md";

	/** Value alignment in row direction: 'start' (left) or 'end' (right). */
	@Prop() align: "start" | "end" = "start";

	/** Applies form-control typography to both keys and values. */
	@Prop({ reflect: true }) variant?: "form";

	/** Limits the key column width in row direction. */
	@Prop({ reflect: true }) keywidth = false;

	/** Removes gap between pairs when true. */
	@Prop() noGap = false;

	componentWillRender() {
		this.el.setAttribute("direction", this.direction);
		this.el.setAttribute("size", this.size);
		this.el.setAttribute("align", this.align);
		if (this.noGap) {
			this.el.setAttribute("no-gap", "");
		} else {
			this.el.removeAttribute("no-gap");
		}
	}

	render() {
		return <Host />;
	}
}
